public class Main {public static void main(String[]args){System.out.println("Договор: арифметические операции изменяют и возвращают текущий объект; следующий вызов использует его новое значение.");Rational a=new Rational(1,2),b=new Rational(1,3);System.out.println(a.add(b)+"; "+a.subtract(b)+"; "+a.multiply(b)+"; "+a.divide(b));Rational[]input=new Rational[args.length];for(int i=0;i<args.length;i++){String[]parts=args[i].split("/");input[i]=new Rational(Long.parseLong(parts[0]),Long.parseLong(parts[1]));}System.out.println("Введено через аргументы: "+java.util.Arrays.toString(input));Rational.transform(input);System.out.println("Результат: "+java.util.Arrays.toString(input));}}
